const ex = $input.first().json;
const executionId = String(ex.execution?.id || ex.id || '');
const step = ex.node?.name || 'error_trigger';
const raw = ex.execution?.error?.message || ex.message || JSON.stringify(ex).slice(0, 400);
const safe = String(raw).replace(/\b(?:xox[baprs]-|xapp-)[A-Za-z0-9-]+/g, '[REDACTED]').replace(/\bBearer\s+[A-Za-z0-9._\-]+/gi, 'Bearer [REDACTED]').replace(/https?:\/\/\S+/g, '[url]').slice(0, 500);
const failureText = safe.startsWith('TRANSCRIPT FETCH FAILED - ') ? safe : ('TRANSCRIPT FETCH FAILED - ' + step + ': ' + safe);
const channel = String($env.SLACK_ALERT_CHANNEL || '').trim();
const healthUrl = String($env.HEALTHCHECK_TRANSCRIPTS_URL || '').replace(/\/$/, '');
return [{ json: { executionId, step, raw: safe, failureText, channel, healthUrl } }];
